// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** A report of the period not read against the clinical diagnosis yet. */
export interface CorrelationWorkItemOut {
  source: "Lab" | "Imaging";
  lab_result_id: number | null;
  imaging_order_id: number | null;
  patient_id: number;
  patient_name: string;
  mrn: string;
  /** The lab test's name, or the modality and the body part */
  examination: string;
  reported_at: string;
  /** The requisition's clinical notes, or the order's clinical indication */
  clinical_context: string | null;
}

export interface CorrelationIn {
  source: "Lab" | "Imaging";
  /** Lab: the published histopathology or cytology result */
  lab_result_id?: number | null;
  /** Imaging: the reported CT or MRI examination */
  imaging_order_id?: number | null;
  /** The clinical diagnosis the report is read against */
  clinical_diagnosis: string;
  outcome: "Correlates" | "PartlyCorrelates" | "DoesNotCorrelate" | "NotAssessable";
  /** Required unless the outcome is Correlates */
  note?: string | null;
}

/** A correlation review: never changed; a later review of the same report counts instead. */
export interface CorrelationOut {
  correlation_id: number;
  source: "Lab" | "Imaging";
  lab_result_id: number | null;
  imaging_order_id: number | null;
  patient_id: number;
  patient_name: string;
  mrn: string;
  examination: string;
  clinical_diagnosis: string;
  outcome: "Correlates" | "PartlyCorrelates" | "DoesNotCorrelate" | "NotAssessable";
  note: string | null;
  reviewed_by: number;
  reviewed_by_name: string;
  reviewed_at: string;
}

/** Reports to read against the clinical diagnosis (MSDS CQI 100) — GET /api/v1/diagnostics/correlations/worklist (who may call: holders of diagnostics.correlation.review). */
export function correlationWorklist(query?: { source?: "Lab" | "Imaging" | null; date_from?: string | null; date_to?: string | null; limit?: number }): Promise<CorrelationWorkItemOut[]> {
  return api<CorrelationWorkItemOut[]>("GET", withQuery(`/diagnostics/correlations/worklist`, query), undefined);
}

/** Record whether a report correlates with the clinical diagnosis — POST /api/v1/diagnostics/correlations (who may call: holders of diagnostics.correlation.review). */
export function recordCorrelation(body: CorrelationIn): Promise<CorrelationOut> {
  return api<CorrelationOut>("POST", `/diagnostics/correlations`, body, { idempotent: true });
}

/** The register of correlation reviews — GET /api/v1/diagnostics/correlations (who may call: holders of diagnostics.quality.view or diagnostics.correlation.review). */
export function correlationRegister(query?: { date_from?: string | null; date_to?: string | null; source?: "Lab" | "Imaging" | null; outcome?: "Correlates" | "PartlyCorrelates" | "DoesNotCorrelate" | "NotAssessable" | null; limit?: number }): Promise<CorrelationOut[]> {
  return api<CorrelationOut[]>("GET", withQuery(`/diagnostics/correlations`, query), undefined);
}
